import numpy as np

def process_large_matrix(matrix_data):
    # Convert input data to a NumPy array for ultra-fast processing
    arr = np.array(matrix_data)
    
    # Initialize an all-zero matrix of the exact same size
    # This automatically satisfies: "if value is not 2, replace with 0"
    output = np.zeros_like(arr)
    
    # 1. Identify where the value is 2
    mask_two = (arr == 2)
    
    # 2. Generate random floats (0.0 to 1.0) across the entire matrix shape
    rand_floats = np.random.random(arr.shape)
    
    # 3. Generate arrays of random integers for the new percentage buckets
    # Note: np.random.randint high parameter is exclusive, so we add +1 to the upper limits
    rand_ints_5_9 = np.random.randint(5, 10, size=arr.shape)     # 5 to 9
    rand_ints_10_19 = np.random.randint(10, 20, size=arr.shape) # 10 to 19
    
    # 4. Apply the new percentage distributions where the original value is 2:
    
    # Tier A: 20% become 0 (This is already handled because 'output' starts as all zeros)
    
    # Tier B: 70% become a number between 5 and 9 (0.20 <= float < 0.90)
    seventy_percent_mask = mask_two & (rand_floats >= 0.20) & (rand_floats < 0.90)
    output[seventy_percent_mask] = rand_ints_5_9[seventy_percent_mask]
    
    # Tier C: 10% become a number between 10 and 19 (float >= 0.90)
    ten_percent_mask = mask_two & (rand_floats >= 0.90)
    output[ten_percent_mask] = rand_ints_10_19[ten_percent_mask]
    
    # Convert back to native Python lists and save to text file
    with open("processed_matrix.txt", "w") as f:
        f.write("matrix = [\n")
        for row in output:
            f.write(f"    {list(row)},\n")
        f.write("]\n")

